.quiz-btn-ghost { background: transparent; color: #7f8c8d; border: 1px solid #cfd8dc; padding: 0.2em 0.8em; font-size: 0.8em; }
.quiz-btn-ghost:hover { background: #f4f6f7; color: #2c3e50; }

.quiz-feedback { min-height: 1.4em; margin: 0.5em 0; line-height: 1.4; }
